package com.highalchighlight;

import com.google.inject.Provides;
import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.KeyCode;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
		name = "High Alc Profit",
		description = "Highlights any item in your backpack or bank that would be profit to high alc",
		tags = {"highlight", "items", "overlay"}
)
public class HighAlcHighlightPlugin extends Plugin {
	@Inject
	private Client client;

	@Inject
	private ItemManager itemManager;

	@Inject
	private ConfigManager configManager;

	@Inject
	private HighAlcHighlightOverlay overlay;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private HighAlcHighlightConfig config;

	@Provides
	HighAlcHighlightConfig provideConfig(ConfigManager configManager) {
		return configManager.getConfig(HighAlcHighlightConfig.class);
	}

	@Override
	protected void startUp() throws Exception
	{
		overlayManager.add(overlay);
	}

	@Override
	protected void shutDown() throws Exception
	{
		overlayManager.remove(overlay);
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (event.getGroup().equals(HighAlcHighlightConfig.GROUP))
		{
			overlay.invalidateCache();
		}
	}

	@Subscribe(priority = -1)
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		if (!client.isKeyPressed(KeyCode.KC_SHIFT))
		{
			return;
		}

		final MenuEntry entry = event.getMenuEntry();
		if (!"Examine".equals(entry.getOption()))
		{
			return;
		}

		final int widgetInterfaceId = entry.getParam1() >> 16;
		final int inventoryInterfaceId = InterfaceID.Inventory.ITEMS >> 16;
		final int bankInterfaceId = InterfaceID.Bankmain.ITEMS >> 16;
		final int bankSideInterfaceId = InterfaceID.Bankside.ITEMS >> 16;

		final ItemContainer container;
		if (widgetInterfaceId == bankInterfaceId)
		{
			container = client.getItemContainer(InventoryID.BANK);
		}
		else if (widgetInterfaceId == inventoryInterfaceId || widgetInterfaceId == bankSideInterfaceId)
		{
			container = client.getItemContainer(InventoryID.INVENTORY);
		}
		else
		{
			return;
		}

		if (container == null)
		{
			return;
		}

		final Item item = container.getItem(entry.getParam0());
		if (item == null || item.getId() == -1)
		{
			return;
		}

		int itemId = item.getId();
		final ItemComposition comp = itemManager.getItemComposition(itemId);
		if (comp.getNote() != -1)
		{
			itemId = comp.getLinkedNoteId();
		}

		final String itemName = itemManager.getItemComposition(itemId).getName();
		final boolean exactlyExcepted = overlay.isExactException(itemName);
		final boolean wildcardExcepted = !exactlyExcepted && overlay.isException(itemName);

		// If only a wildcard covers this item, don't offer a toggle — the user must edit the list manually
		if (wildcardExcepted)
		{
			return;
		}

		client.getMenu().createMenuEntry(-1)
			.setOption(exactlyExcepted ? "Highlight" : "Don't highlight")
			.setTarget(entry.getTarget())
			.setType(MenuAction.RUNELITE)
			.onClick(e -> toggleException(itemName));
	}

	private void toggleException(String itemName)
	{
		final String lowerName = itemName.toLowerCase();
		final String current = config.exceptions();

		final List<String> list = Arrays.stream(current.split(","))
			.map(String::trim)
			.filter(s -> !s.isEmpty())
			.collect(Collectors.toList());

		final boolean removed = list.removeIf(s -> s.toLowerCase().equals(lowerName));
		if (!removed)
		{
			list.add(itemName);
		}

		configManager.setConfiguration(HighAlcHighlightConfig.GROUP, "exceptions", String.join(",", list));
	}
}

package com.highalchighlight;

import com.google.common.cache.Cache;
import com.google.common.cache.CacheBuilder;
import com.highalchighlight.config.FireRuneSource;
import com.highalchighlight.config.HighlightStyle;
import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.WidgetItemOverlay;
import net.runelite.client.util.ColorUtil;
import net.runelite.client.util.ImageUtil;

import javax.inject.Inject;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Image;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.regex.Pattern;

public class HighAlcHighlightOverlay extends WidgetItemOverlay
{
	private final Client client;
    private final ItemManager itemManager;
    private final HighAlcHighlightConfig config;
    private final ConfigManager configManager;
    private final Cache<Long, Image> fillCache;
    private Set<String> exceptionExact = Collections.emptySet();
    private List<Pattern> exceptionPatterns = Collections.emptyList();
    private static final double GE_TAX_RATE = 0.02;
    private static final int GE_TAX_THRESHOLD = 5000000;
    private static final String INVENTORY_TAGS_GROUP = "inventorytags";
    private static final String INVENTORY_TAGS_KEY_PREFIX = "tag_";
    @Inject
    private HighAlcHighlightOverlay(Client client, ItemManager itemManager, HighAlcHighlightConfig config, ConfigManager configManager)
    {
    	this.client = client;
        this.itemManager = itemManager;
        this.config = config;
        this.configManager = configManager;
        fillCache = CacheBuilder.newBuilder()
            .concurrencyLevel(1)
            .maximumSize(32)
            .build();
        showOnInventory();
        showOnBank();
        rebuildExceptionSet();
    }

    @Override
    public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem itemWidget)
    {
        if (checkInterfaceIsHighlightable(itemWidget)) {
            double gePrice = getAdjustedGePrice(itemId);
            long profitPerCast = getProfit(itemId, gePrice);
            boolean isSellable = isSellable(itemId);

            if ((profitPerCast > 0) && (isSellable || config.highlightUnsellables())) {
                if (config.respectInventoryTags() && hasInventoryTag(itemId)) {
                    return;
                }

                final String itemName = itemManager.getItemComposition(itemId).getName();
                if (isException(itemName)) {
                    return;
                }

                Color colorToUse = getColor(profitPerCast, isSellable);
                Rectangle bounds = itemWidget.getCanvasBounds();

                if (config.highlightStyle() == HighlightStyle.OUTLINE) {
                    final BufferedImage outline = itemManager.getItemOutline(itemId, itemWidget.getQuantity(), colorToUse);
                    graphics.drawImage(outline, (int) bounds.getX(), (int) bounds.getY(), null);
                } else if (config.highlightStyle() == HighlightStyle.UNDERLINE) {
                    int y = (int) bounds.getY() + (int) bounds.getHeight() + 2;
                    graphics.setColor(colorToUse);
                    graphics.drawLine((int) bounds.getX(), y, (int) bounds.getX() + (int) bounds.getWidth(), y);
                } else if (config.highlightStyle() == HighlightStyle.FILL) {
                    final Image fill = getFillImage(colorToUse, itemId, itemWidget.getQuantity());
                    graphics.drawImage(fill, (int) bounds.getX(), (int) bounds.getY(), null);
                }
            }
        }
    }

	private boolean checkInterfaceIsHighlightable(WidgetItem itemWidget)
	{
		Widget bankWidget = client.getWidget(InterfaceID.Bankmain.ITEMS);
		Widget inventoryWidget = client.getWidget(InterfaceID.Inventory.ITEMS);
		Widget bankInventoryWidget = client.getWidget(InterfaceID.Bankside.ITEMS);

		boolean isBankItem = bankWidget != null && bankWidget.getId() == itemWidget.getWidget().getId();
		boolean isInventoryItem = inventoryWidget != null && inventoryWidget.getId() == itemWidget.getWidget().getId();
		boolean isBankInventoryItem = bankInventoryWidget != null && bankInventoryWidget.getId() == itemWidget.getWidget().getId();

		if (config.neverHighlightInventory() && (isInventoryItem || isBankInventoryItem))
		{
			return false;
		}

		if (config.getHighlightLocation() == HighAlcHighlightConfig.HighlightLocationType.BANK)
		{
			return isBankItem;
		}

		if (config.getHighlightLocation() == HighAlcHighlightConfig.HighlightLocationType.INVENTORY)
		{
			return isInventoryItem || isBankInventoryItem;
		}

		return true;
	}

    double getAdjustedGePrice(int itemId)
    {
        double gePrice = itemManager.getItemPrice(itemId);
        if (gePrice * GE_TAX_RATE >= 1)
        {
            if (gePrice * GE_TAX_RATE > GE_TAX_THRESHOLD) {
                gePrice -= GE_TAX_THRESHOLD;
            } else {
                gePrice -= (int)(gePrice * GE_TAX_RATE);
            }
        }
        return gePrice;
    }

    long getProfit(int itemId, double gePrice)
    {
        ItemComposition itemDef = itemManager.getItemComposition(itemId);

        int haPrice = itemDef.getHaPrice();

        long fireRunePrice = itemManager.getItemPrice(ItemID.FIRERUNE);
        long natureRunePrice;
        if (config.useGE())
        {
            natureRunePrice = itemManager.getItemPrice(ItemID.NATURERUNE);
        }
        else
        {
            natureRunePrice = config.overridePrice();
        }
        long fireRuneMultiplier = 0;
        if (config.fireRuneSource() == FireRuneSource.RUNES) {
            fireRuneMultiplier = 5;
        }

        double natureRuneMultiplier = 1.0;
        if (config.useBryoStaff()) {
            natureRuneMultiplier = 0.9375;
        }

        long castCost = (fireRunePrice * fireRuneMultiplier) + (long) Math.ceil(natureRunePrice * natureRuneMultiplier);

        if (config.useGEPrices())
        {
            return (long)(haPrice - gePrice - castCost);
        }
        else
        {
            return haPrice - castCost;
        }
    }

    private Image getFillImage(Color color, int itemId, int qty)
    {
        long key = ((long) itemId << 32) | qty;
        Image image = fillCache.getIfPresent(key);
        if (image == null)
        {
            final Color fillColor = ColorUtil.colorWithAlpha(color, config.fillOpacity());
            image = ImageUtil.fillImage(itemManager.getImage(itemId, qty, false), fillColor);
            fillCache.put(key, image);
        }
        return image;
    }

    void invalidateCache()
    {
        fillCache.invalidateAll();
        rebuildExceptionSet();
    }

    private void rebuildExceptionSet()
    {
        String exceptions = config.exceptions();
        if (exceptions.isEmpty())
        {
            exceptionExact = Collections.emptySet();
            exceptionPatterns = Collections.emptyList();
            return;
        }

        Set<String> exact = new HashSet<>();
        List<Pattern> patterns = new ArrayList<>();

        for (String entry : exceptions.split(","))
        {
            String trimmed = entry.trim();
            if (trimmed.isEmpty())
            {
                continue;
            }
            if (trimmed.contains("*"))
            {
                patterns.add(globToPattern(trimmed));
            }
            else
            {
                exact.add(trimmed.toLowerCase());
            }
        }

        exceptionExact = exact;
        exceptionPatterns = patterns;
    }

    private static Pattern globToPattern(String glob)
    {
        String[] parts = glob.toLowerCase().split("\\*", -1);
        StringBuilder regex = new StringBuilder("^");
        for (int i = 0; i < parts.length; i++)
        {
            if (i > 0)
            {
                regex.append(".*");
            }
            regex.append(Pattern.quote(parts[i]));
        }
        regex.append("$");
        return Pattern.compile(regex.toString());
    }

    boolean isExactException(String itemName)
    {
        return exceptionExact.contains(itemName.toLowerCase());
    }

    boolean isException(String itemName)
    {
        String lower = itemName.toLowerCase();
        if (exceptionExact.contains(lower))
        {
            return true;
        }
        for (Pattern pattern : exceptionPatterns)
        {
            if (pattern.matcher(lower).matches())
            {
                return true;
            }
        }
        return false;
    }

    private boolean hasInventoryTag(int itemId)
    {
        String tag = configManager.getConfiguration(INVENTORY_TAGS_GROUP, INVENTORY_TAGS_KEY_PREFIX + itemId);
        return tag != null && !tag.isEmpty();
    }

    boolean isSellable(int itemId) {
        return itemManager.getItemComposition(itemManager.canonicalize(itemId)).isGeTradeable();
    }

    Color getColor(long profitPerCast, boolean isSellable)
    {
        if (!isSellable) {
            return config.getUnsellableColour();
        }

        if (config.useGradientMode()) {
            double percent = Math.min(((double) profitPerCast) / config.highProfitValue(), 1.0);

            return getGradientColor(config.getColour(), config.getHighProfitColour(), percent);
        } else {
            if (profitPerCast >= config.highProfitValue()) {
                return config.getHighProfitColour();
            } else {
                return config.getColour();
            }
        }
    }

    private Color getGradientColor(Color lowColor, Color highColor, double percent)
    {
        int newRed = findStep(lowColor.getRed(), highColor.getRed(), percent);
        int newGreen = findStep(lowColor.getGreen(), highColor.getGreen(), percent);
        int newBlue = findStep(lowColor.getBlue(), highColor.getBlue(), percent);

        return new Color(newRed, newGreen, newBlue);
    }

    private int findStep(int low, int high, double percent)
    {
        return (int) (low + (high-low)*percent);
    }
}

package com.highalchighlight;

import lombok.AllArgsConstructor;
import net.runelite.client.config.*;
import com.highalchighlight.config.FireRuneSource;
import com.highalchighlight.config.HighlightStyle;

import java.awt.Color;

@ConfigGroup(HighAlcHighlightConfig.GROUP)
public interface HighAlcHighlightConfig extends Config
{
	String GROUP = "highalchighlight";@AllArgsConstructor
	enum HighlightLocationType
	{
		BOTH("Both"),
		BANK("Bank"),
		INVENTORY("Inventory");

		private final String value;

		@Override
		public String toString()
		{
			return value;
		}
	}

	@ConfigSection(
			name = "Highlighting Colour and Style",
			description = "Highlighting config",
			position = 0
	)
	String highlighting = "Highlighting";

	@ConfigItem(
		position = 1,
		keyName = "useGradientMode",
		name = "Gradient Mode",
		description = "Enabling this setting will cause items to be highlighted in a gradient color from your Highlight Colour to your High-Profit Colour based on profitability.",
		section = highlighting
	)
	default boolean useGradientMode() {return true;}

	@ConfigItem(
		position = 2,
		keyName = "HighlightColour",
		name = "Highlight Colour",
		description = "Highlight colour of profitable items",
		section = highlighting
	)
	default Color getColour() {return Color.WHITE;}

	@ConfigItem(
		position = 3,
		keyName = "highProfitValue",
		name = "High-Profit Threshold",
		description = "The price for high-profit highlighting.",
		section = highlighting
	)
	default int highProfitValue() { return 300; }

	@ConfigItem(
		position = 4,
		keyName = "highProfitColour",
		name = "High-Profit Colour",
		description = "Highlight colour of items that are high-profit.",
		section = highlighting
	)
	default Color getHighProfitColour() {return Color.GREEN;}

	@ConfigItem(
		position = 5,
		keyName = "unsellableHighlightColour",
		name = "Unsellables Colour",
		description = "Colour to show if Highlight Unsellables is checked",
		section = highlighting
	)
	default Color getUnsellableColour() {return Color.YELLOW;}


	@ConfigItem(
		position = 6,
		keyName = "highlightStyle",
		name = "Highlight Style",
		description = "How profitable items are highlighted.",
		section = highlighting
	)
	default HighlightStyle highlightStyle() {return HighlightStyle.OUTLINE;}

	@Range(max = 255)
	@ConfigItem(
		position = 7,
		keyName = "fillOpacity",
		name = "Fill Opacity",
		description = "Opacity of the fill highlight (only used when Highlight Style is Fill).",
		section = highlighting
	)
	default int fillOpacity() {return 50;}

	@ConfigItem(
		position = 8,
		keyName = "respectInventoryTags",
		name = "Respect Inventory Tags",
		description = "Skip highlighting items that have an Inventory Tag.",
		section = highlighting
	)
	default boolean respectInventoryTags() {return true;}

	@ConfigItem(
			position = 9,
			keyName = "usingBryo",
			name = "Using Bryophyta's Staff",
			description = "Configures if you are using Bryophyta's Staff."
	)
	default boolean useBryoStaff() {return false;}

	@ConfigItem(
			position = 10,
			keyName = "fireRuneSource",
			name = "Source of Fire Runes",
			description = "Configures what source of fire runes you are using."
	)
	default FireRuneSource fireRuneSource() { return FireRuneSource.STAFF; }

	@ConfigItem(
			position = 11,
			keyName = "useGE",
			name = "Use GE Price for Nature Runes",
			description = "Fetch the price of Nature Runes from the GE (Ironmen should set this to off)"
	)
	default boolean useGE() {return true;}

	@ConfigItem(
			position = 12,
			keyName = "useGEPrices",
			name = "Use GE Price for Item",
			description = "Fetch the price of the item for High Alc calculation, otherwise just uses HA Value - Cast Cost"
	)
	default boolean useGEPrices() {return true;}

	@ConfigItem(
			position = 13,
			keyName = "overridePrice",
			name = "Nature rune cost",
			description = "If the Nature Rune GE price is not used this is the price for Nature Runes that will be used."
	)
	default int overridePrice() {return 203;}

	@ConfigItem(
			position = 14,
			keyName = "highlightUnsellables",
			name = "Highlight Unsellables",
			description = "If enabled, highlights items that would make a profit but cannot be sold on the GE"
	)
	default boolean highlightUnsellables() {return true;}

	@ConfigItem(
			position = 15,
			keyName = "highlightLocation",
			name = "Highlight",
			description = "Whether to highlight items in the bank, inventory, or both."
	)
	default HighlightLocationType getHighlightLocation() {return HighlightLocationType.BOTH;}

	@ConfigItem(
			position = 16,
			keyName = "neverHighlightInventory",
			name = "Never Highlight Inventory",
			description = "If enabled, items will never be highlighted in your inventory, even when the bank is closed."
	)
	default boolean neverHighlightInventory() {return false;}

	@ConfigItem(
		position = 17,
		keyName = "exceptions",
		name = "Exception List",
		description = "Comma-separated list of item names to never highlight. Use Shift+right-click on an item to add it. Wildcarded items must be edited directly"
	)
	default String exceptions()
	{
		return "";
	}
}
